import{_ as e,c as o,o as r,ag as d}from"./chunks/framework.CoPVQkzc.js";const g=JSON.parse('{"title":"JavaScript Editor","description":"The built-in code editor features and shortcuts","frontmatter":{"title":"JavaScript Editor","description":"The built-in code editor features and shortcuts"},"headers":[],"relativePath":"engine/javascript_editor.md","filePath":"engine/javascript_editor.md","lastUpdated":1788476353000}'),a={name:"engine/javascript_editor.md"};function n(i,t,s,c,l,h){return r(),o("div",null,t[0]||(t[0]=[d('<h1 id="javascript-editor" tabindex="-1">JavaScript Editor <a class="header-anchor" href="#javascript-editor" aria-label="Permalink to &quot;JavaScript Editor&quot;">​</a></h1><p>The JavaScript Editor is the built-in code editor used throughout OIE for writing filter rules, transformer steps, channel scripts, and code templates. It is built on the RSyntaxTextArea library and provides syntax highlighting, auto-completion, and other features to aid development.</p><h2 id="features" tabindex="-1">Features <a class="header-anchor" href="#features" aria-label="Permalink to &quot;Features&quot;">​</a></h2><h3 id="syntax-highlighting" tabindex="-1">Syntax highlighting <a class="header-anchor" href="#syntax-highlighting" aria-label="Permalink to &quot;Syntax highlighting&quot;">​</a></h3><p>The editor provides color-coded syntax highlighting for JavaScript, including OIE-specific keywords and variables such as <code>msg</code>, <code>tmp</code>, <code>connectorMap</code>, <code>channelMap</code>, <code>logger</code>, <code>FileUtil</code>, <code>DateUtil</code>, and map shorthand functions (<code>$c</code>, <code>$g</code>, <code>$s</code>, <code>$r</code>, etc.).</p><h3 id="auto-completion" tabindex="-1">Auto-completion <a class="header-anchor" href="#auto-completion" aria-label="Permalink to &quot;Auto-completion&quot;">​</a></h3><p>Press <code>Ctrl+Space</code> to open the auto-completion popup. It provides suggestions for:</p><ul><li>Built-in JavaScript functions and objects</li><li>OIE utility classes and methods (<code>ChannelUtil</code>, <code>DateUtil</code>, <code>FileUtil</code>, <code>DatabaseConnectionFactory</code>, <code>SMTPConnectionFactory</code>, etc.)</li><li>Variable map methods (<code>channelMap.put</code>, <code>globalMap.get</code>, etc.)</li><li>Code template functions available in the current context</li></ul><p>Auto-completion can also be triggered automatically after typing certain characters (<code>.</code> by default). These settings are configurable under Code Editor Preferences.</p><h3 id="find-and-replace" tabindex="-1">Find and replace <a class="header-anchor" href="#find-and-replace" aria-label="Permalink to &quot;Find and replace&quot;">​</a></h3><p><code>Ctrl+F</code> opens the Find / Replace dialog:</p><ul><li><strong>Find text</strong> / <strong>Replace with</strong>: Search and replace fields with history dropdowns</li><li><strong>Direction</strong>: Forward or Backward</li><li><strong>Wrap Search</strong>: Search wraps around the end of the file</li><li><strong>Match Case</strong>: Toggle case sensitivity</li><li><strong>Regular Expression</strong>: Use regular expressions for search patterns</li><li><strong>Whole Word</strong>: Match whole words only</li></ul><h3 id="code-folding" tabindex="-1">Code folding <a class="header-anchor" href="#code-folding" aria-label="Permalink to &quot;Code folding&quot;">​</a></h3><p>Collapse and expand code blocks:</p><ul><li>Click the fold icons in the gutter (left margin)</li><li>Collapse functions, if/else blocks, loops, and other block structures</li><li>Use the Folding submenu in the context menu or keyboard shortcuts to collapse/expand folds</li></ul><h2 id="context-menu" tabindex="-1">Context menu <a class="header-anchor" href="#context-menu" aria-label="Permalink to &quot;Context menu&quot;">​</a></h2><p>Right-click in the editor to access:</p><table tabindex="0"><thead><tr><th>Option</th><th>Description</th></tr></thead><tbody><tr><td><strong>Undo / Redo</strong></td><td>Undo/redo recent changes</td></tr><tr><td><strong>Cut / Copy / Paste / Delete</strong></td><td>Standard clipboard operations</td></tr><tr><td><strong>Select All</strong></td><td>Select all code in the editor</td></tr><tr><td><strong>Find/Replace</strong></td><td>Open the find/replace dialog</td></tr><tr><td><strong>Find Next</strong></td><td>Find the next occurrence</td></tr><tr><td><strong>Clear Marked Occurrences</strong></td><td>Clear highlighted search results</td></tr><tr><td><strong>Folding</strong></td><td>Submenu: Collapse Fold, Expand Fold, Collapse All Folds, Collapse All Comment Folds, Expand All Folds</td></tr><tr><td><strong>Display</strong></td><td>Submenu: Show Tab Lines, Show Whitespace, Show Line Endings, Wrap Lines</td></tr><tr><td><strong>Code</strong></td><td>Submenu: Format Code, Toggle Comment</td></tr><tr><td><strong>Macro</strong></td><td>Submenu: Begin Macro, End Macro, Playback Macro</td></tr><tr><td><strong>View User API</strong></td><td>Open the User API documentation</td></tr></tbody></table><h2 id="keyboard-shortcuts" tabindex="-1">Keyboard shortcuts <a class="header-anchor" href="#keyboard-shortcuts" aria-label="Permalink to &quot;Keyboard shortcuts&quot;">​</a></h2><p>Default shortcuts (on Windows/Linux):</p><table tabindex="0"><thead><tr><th>Shortcut</th><th>Action</th></tr></thead><tbody><tr><td><code>Ctrl+Space</code></td><td>Open auto-completion popup</td></tr><tr><td><code>Ctrl+F</code></td><td>Find and Replace</td></tr><tr><td><code>Ctrl+G</code></td><td>Find Next</td></tr><tr><td><code>Ctrl+Z</code></td><td>Undo</td></tr><tr><td><code>Ctrl+Y</code></td><td>Redo</td></tr><tr><td><code>Ctrl+/</code></td><td>Toggle line comment</td></tr><tr><td><code>Ctrl+Shift+F</code></td><td>Format code</td></tr><tr><td><code>Ctrl+D</code></td><td>Delete line</td></tr><tr><td><code>Ctrl+J</code></td><td>Join lines</td></tr><tr><td><code>Ctrl+[</code></td><td>Go to matching bracket</td></tr><tr><td><code>Ctrl+A</code></td><td>Select all</td></tr><tr><td><code>Ctrl+-</code></td><td>Collapse fold</td></tr><tr><td><code>Ctrl++</code></td><td>Expand fold</td></tr><tr><td><code>Tab</code></td><td>Indent selected lines</td></tr><tr><td><code>Shift+Tab</code></td><td>Unindent selected lines</td></tr></tbody></table><p>All keyboard shortcuts can be remapped under <strong>Settings &gt; Administrator &gt; Code Editor Preferences</strong> using the Shortcut Key Mappings table.</p><h2 id="reference-list" tabindex="-1">Reference list <a class="header-anchor" href="#reference-list" aria-label="Permalink to &quot;Reference list&quot;">​</a></h2><p>Adjacent to the script editor, the <strong>Reference List</strong> panel provides quick access to categorized functions, code snippets, and variables. Use the <strong>Category</strong> dropdown to filter by category and the <strong>Filter</strong> field to search within the selected category.</p><h3 id="categories" tabindex="-1">Categories <a class="header-anchor" href="#categories" aria-label="Permalink to &quot;Categories&quot;">​</a></h3><ul><li><strong>Conversion Functions</strong> - Data format conversion helpers</li><li><strong>Logging and Alerts</strong> - Logging and alert functions</li><li><strong>Database Functions</strong> - Database connection and query helpers</li><li><strong>Utility Functions</strong> - File I/O, routing, attachments, and other utilities</li><li><strong>Date Functions</strong> - Date formatting and conversion</li><li><strong>Message Functions</strong> - Message access and manipulation</li><li><strong>Response Transformer</strong> - Response transformation helpers</li><li><strong>Map Functions</strong> - Variable map operations</li><li><strong>Channel Functions</strong> - Channel utility methods</li><li><strong>Postprocessor Functions</strong> - Postprocessor-specific references</li><li><strong>User Defined Code</strong> - User-created code templates (code type)</li><li><strong>User Defined Functions</strong> - User-created code templates (function type)</li></ul><p>Click an item to see its description, then drag it into the editor to insert the code.</p><h3 id="variables" tabindex="-1">Variables <a class="header-anchor" href="#variables" aria-label="Permalink to &quot;Variables&quot;">​</a></h3><p>Variables are included in the reference list alongside functions and code snippets. Which variables appear depends on the current script context. Examples include:</p><ul><li><code>msg</code> (inbound message in filter/transformer scripts), <code>tmp</code> (outbound template in filter/transformer scripts)</li><li><code>connectorMessage</code> (in connector scripts)</li><li><code>message</code> (completed message object in the postprocessor)</li><li><code>response</code>, <code>responseStatus</code>, <code>responseErrorMessage</code>, <code>responseStatusMessage</code> (in response transformer scripts)</li><li>Map objects: <code>connectorMap</code>, <code>channelMap</code>, <code>sourceMap</code>, <code>globalChannelMap</code>, <code>globalMap</code>, <code>configurationMap</code>, <code>responseMap</code></li><li><code>logger</code>, <code>router</code>, <code>alerts</code>, <code>replacer</code>, <code>contextFactory</code></li></ul><h2 id="code-editor-preferences" tabindex="-1">Code editor preferences <a class="header-anchor" href="#code-editor-preferences" aria-label="Permalink to &quot;Code editor preferences&quot;">​</a></h2><p>Configure editor behavior in <strong>Settings &gt; Administrator &gt; Code Editor Preferences</strong>:</p><table tabindex="0"><thead><tr><th>Preference</th><th>Description</th></tr></thead><tbody><tr><td><strong>Auto-Complete Characters</strong></td><td>Characters that trigger the auto-completion popup (default: <code>.</code>)</td></tr><tr><td><strong>Include Letters</strong></td><td>If enabled, auto-completion triggers after any letter is typed</td></tr><tr><td><strong>Activation Delay (ms)</strong></td><td>Time to wait after typing a trigger character before showing the popup (default: 300 ms)</td></tr><tr><td><strong>Shortcut Key Mappings</strong></td><td>Table of all remappable editor actions with their current keyboard shortcuts; double-click a shortcut to change it</td></tr><tr><td><strong>Restore Defaults</strong></td><td>Reset all shortcut key mappings to their defaults</td></tr></tbody></table>',33)]))}const u=e(a,[["render",n]]);export{g as __pageData,u as default};
